css:
.btgt{
  --g900:#0F3D1E;--g800:#14501F;--g700:#1B5E20;--g600:#2E7D32;--g500:#43A047;--g400:#66BB6A;
  --g100:#E8F5E9;--g50:#F3FAF4;--ink:#152418;--mut:#5F6F63;--line:#DCE9DE;--red:#C62828;--amb:#E65100;
  --card:#FFFFFF;--shadow:0 1px 2px rgba(15,61,30,.06),0 4px 14px rgba(15,61,30,.07);--r:14px;
  font-family:'Inter','Segoe UI',system-ui,sans-serif;background:var(--g50);color:var(--ink);
  font-size:14px;line-height:1.45;display:block;position:relative;min-height:100vh;padding:16px 18px;box-sizing:border-box;
}
.navbar{display:none;}
.web-footer{display:none;}
.btgt *{box-sizing:border-box}
.btgt .btgt-head{
    display:flex;
    align-items:center;
    gap:12px;
    flex-wrap:wrap;
    margin-bottom:16px;

    /* space for Portal Home fullscreen back button */
    padding-left:44px;
}
.btgt .btgt-title{font-size:16px;font-weight:800;color:var(--g800);letter-spacing:.3px}
.btgt select,.btgt input[type=date]{height:34px;padding:5px 10px;border:1px solid #b0bec5;border-radius:8px;font-size:13px;background:#fff;color:var(--ink)}
.btgt .btgt-btn{height:34px;padding:6px 16px;border:none;border-radius:8px;background:var(--g600);color:#fff;font-weight:700;font-size:13px;cursor:pointer}
.btgt .btgt-chip{height:34px;padding:6px 12px;border:1px solid #a5d6a7;border-radius:8px;background:#e8f5e9;color:#2e7d32;font-weight:600;font-size:12px;cursor:pointer}
.btgt .btgt-chip.active{background:#2e7d32;color:#fff;border-color:#2e7d32}
.btgt .m-kpis{display:flex;gap:10px;padding:14px 16px;background:#F3FAF4;border:1px solid #DCE9DE;border-radius:12px;flex-wrap:wrap;margin-bottom:14px}
.btgt .m-kpi{flex:1;min-width:100px;text-align:center}
.btgt .m-kpi b{display:block;font-size:18px;color:#14501F}
.btgt .m-kpi b.r{color:#C62828}.btgt .m-kpi b.a{color:#E65100}
.btgt .m-kpi span{font-size:9px;color:#5F6F63;text-transform:uppercase;letter-spacing:.6px;font-weight:700}
.btgt .tbl{width:100%;border-collapse:collapse;font-size:12px}
.btgt .tbl th,.btgt .tbl td{border:1px solid #E3EEE5;padding:6px 8px;text-align:left;white-space:nowrap}
.btgt .tbl th{background:#37474f;color:#fff;font-weight:700}
.btgt .tbl td.num,.btgt .tbl th.num{text-align:right}
.btgt .formula{background:#F3FAF4;border-left:3px solid var(--g500);padding:10px 12px;font-size:11.5px;color:#37474f;border-radius:6px;line-height:1.6}
.btgt .formula code{background:#E8F5E9;padding:1px 5px;border-radius:4px;font-size:11px}
.btgt .note{color:var(--mut);font-size:12px;padding:8px}


/* ===== extracted target modal styles ===== */
.btgt .num {
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum";
}
/* ============================================================
   CARDS
   ============================================================ */
.btgt .card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: var(--r);
    padding: 14px 16px;
    box-shadow: var(--shadow);
    margin-bottom: 14px;
}
.btgt .card h3 {
    font-size: 12.5px;
    font-weight: 700;
    letter-spacing: .6px;
    color: var(--g800);
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
    text-transform: uppercase;
}
/* ============================================================
   PILLS
   ============================================================ */
.btgt .pill {
    display: inline-block;
    padding: 3px 9px;
    border-radius: 99px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .5px;
}
.btgt .p-g {
    background: #E8F5E9;
    color: #1B5E20;
}
.btgt .p-r {
    background: #FDECEA;
    color: #C62828;
}
.btgt .p-gr {
    background: #ECEFF1;
    color: #546E7A;
}
.btgt .m-kpis {
    display: flex;
    gap: 10px;
    padding: 14px 22px;
    background: #F3FAF4;
    border-bottom: 1px solid #DCE9DE;
    flex-wrap: wrap;
    flex-shrink: 0;
}
.btgt .m-kpi {
    flex: 1;
    min-width: 100px;
    text-align: center;
}
.btgt .m-kpi b {
    display: block;
    font-size: 18px;
    color: #14501F;
}
.btgt .m-kpi b.r { color: #C62828; }
.btgt .m-kpi b.a { color: #E65100; }
.btgt .m-kpi span {
    font-size: 9px;
    color: #5F6F63;
    text-transform: uppercase;
    letter-spacing: .6px;
    font-weight: 700;
}
.btgt {
    padding: 16px 22px;
    overflow-y: auto;
    flex: 1;
    color: #152418;
    background: #fff;
}
.btgt .csec {
    border: 1px solid #DCE9DE;
    border-radius: 10px;
    margin-bottom: 10px;
    overflow: hidden;
}
.btgt .csec-h {
    width: 100%;
    background: #F3FAF4;
    border: none;
    padding: 10px 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 700;
    font-size: 12px;
    color: #14501F;
    text-align: left;
    cursor: pointer;
}
.btgt .csec-h .cnt {
    margin-left: auto;
    background: #E8F5E9;
    color: #1B5E20;
    padding: 2px 8px;
    border-radius: 99px;
    font-size: 10px;
}
.btgt .csec-h .cnt.r {
    background: #FDECEA;
    color: #C62828;
}
.btgt .csec-b {
    display: none;
    padding: 12px 14px;
}
.btgt .csec.open .csec-b {
    display: block;
}
.btgt .csec.open .car {
    transform: rotate(180deg);
}
.btgt .car {
    transition: transform .2s;
    font-size: 9px;
}
.btgt .mx-wrap {
    overflow-x: auto;
}
.btgt table {
    border-collapse: collapse;
    width: 100%;
    font-size: 11px;
}
.btgt table th,
.btgt table td {
    border: 1px solid #DCE9DE;
    padding: 5px 8px;
    text-align: right;
    white-space: nowrap;
}
.btgt table th:first-child,
.btgt table td:first-child {
    text-align: left;
}
.btgt table th {
    background: #E8F5E9;
    color: #14501F;
    font-weight: 800;
    font-size: 10px;
    text-transform: uppercase;
}
.btgt table tr.tot td {
    background: #F3FAF4;
    font-weight: 800;
}
.btgt table tr.net td {
    background: #F1F8E9;
    font-weight: 800;
    color: #14501F;
}
.btgt table tr.grp td {
    background: #1B5E20;
    color: #fff;
    font-weight: 800;
    font-size: 9px;
    text-transform: uppercase;
}
.btgt .who {
    display: flex;
    align-items: center;
    gap: 8px;
}
.btgt .ww {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: #E8F5E9;
    color: #1B5E20;
    font-size: 9px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
}
.btgt .wn {
    font-weight: 700;
}
.btgt .gchips {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}
.btgt .gchip {
    flex: 1;
    min-width: 80px;
    border: 1px solid #DCE9DE;
    border-radius: 10px;
    padding: 9px;
    text-align: center;
    background: #F3FAF4;
}
.btgt .gchip b {
    display: block;
    font-size: 16px;
    color: #14501F;
}
.btgt .gchip.r b { color: #C62828; }
.btgt .gchip.a b { color: #E65100; }
.btgt .gchip span {
    font-size: 9px;
    color: #5F6F63;
    text-transform: uppercase;
    font-weight: 700;
}
.btgt .formula {
    background: #F3FAF4;
    border-left: 3px solid #43A047;
    padding: 8px 12px;
    border-radius: 0 8px 8px 0;
    font-size: 11.5px;
    color: #5F6F63;
}
.btgt .note {
    font-size: 11px;
    color: #5F6F63;
}
.btgt .hbar {
    height: 7px;
    border-radius: 99px;
    background: #E8F5E9;
    overflow: hidden;
    flex: 1;
}
.btgt .hbar i {
    display: block;
    height: 100%;
    border-radius: 99px;
    background: linear-gradient(90deg, #43A047, #1B5E20);
}
.btgt .pill {
    display: inline-block;
    padding: 3px 9px;
    border-radius: 99px;
    font-size: 10px;
    font-weight: 800;
}
.btgt .p-g {
    background: #E8F5E9;
    color: #1B5E20;
}
.btgt .p-a {
    background: #FFF3E0;
    color: #E65100;
}
.btgt .p-r {
    background: #FDECEA;
    color: #C62828;
}
.btgt .p-gr {
    background: #ECEFF1;
    color: #546E7A;
}
/* ============================================================
   NOTE / GCHIPS / FORMULA / CSC
   ============================================================ */
.btgt .note {
    font-size: 11px;
    color: var(--mut);
}
.btgt .formula {
    background: var(--g50);
    border-left: 3px solid var(--g500);
    padding: 8px 12px;
    border-radius: 0 8px 8px 0;
    font-size: 11.5px;
    color: var(--mut);
}
.btgt .csec {
    border: 1px solid var(--line);
    border-radius: 10px;
    margin-bottom: 10px;
    overflow: hidden;
}
.btgt .csec-h {
    width: 100%;
    background: var(--g50);
    border: none;
    padding: 10px 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 700;
    font-size: 12px;
    color: var(--g800);
    text-align: left;
}
.btgt .csec-h .cnt {
    margin-left: auto;
    background: var(--g100);
    color: var(--g700);
    padding: 2px 8px;
    border-radius: 99px;
    font-size: 10px;
}
.btgt .csec-h .cnt.r {
    background: #FDECEA;
    color: var(--red);
}
.btgt .csec-b {
    display: none;
    padding: 12px 14px;
}
.btgt .csec.open .csec-b {
    display: block;
}
.btgt .csec.open .car {
    transform: rotate(180deg);
}
.btgt .car {
    transition: transform .2s;
    font-size: 9px;
}
/* ============================================================
   v16 — Daily target tracker (deficit method)
   ============================================================ */
.btgt .tgt-mini {
    margin-top: 6px;
    display: inline-block;
    padding: 2px 9px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.03em;
}
.btgt .tgt-mini.ok { background: #E8F5E9; color: #1B5E20; }
.btgt .tgt-mini.warn { background: #FDECEA; color: #C62828; }
.btgt .tgt-need {
    padding: 16px 18px;
    border-radius: 12px;
    margin-bottom: 14px;
    border-left: 5px solid #C62828;
    background: linear-gradient(135deg, #FFF5F5 0%, #FDECEA 100%);
}
.btgt .tgt-need.ok {
    border-left-color: #2E7D32;
    background: linear-gradient(135deg, #F4FBF5 0%, #E8F5E9 100%);
}
.btgt .tgt-need-l {
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #5F6F63;
}
.btgt .tgt-need-v {
    font-size: 34px;
    font-weight: 800;
    line-height: 1.15;
    margin: 4px 0 2px;
    color: #C62828;
}
.btgt .tgt-need.ok .tgt-need-v { color: #1B5E20; }
.btgt .tgt-need-v span {
    font-size: 15px;
    font-weight: 700;
    color: #5F6F63;
    margin-left: 4px;
}
.btgt .tgt-need-s { font-size: 12px; color: #5F6F63; }
.btgt .tgt-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 8px;
}
.btgt .tgt-cell {
    padding: 9px 12px;
    border: 1px solid #E3EEE5;
    border-radius: 8px;
    background: #FAFCFA;
}
.btgt .tgt-cell span {
    display: block;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #7A8B7E;
    margin-bottom: 3px;
}
.btgt .tgt-cell b { font-size: 14px; font-weight: 800; color: #1B5E20; }
.btgt .tgt-cell b.r { color: #C62828; }
/* Day-by-day bar strip */
.btgt .tgt-strip {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    overflow-x: auto;
    padding: 6px 2px 0;
}
.btgt .tgt-bar {
    flex: 1 0 22px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
}
.btgt .tgt-bar-wrap {
    position: relative;
    width: 100%;
    height: 96px;
    background: #F1F6F2;
    border-radius: 4px;
    overflow: hidden;
}
.btgt .tgt-bar-wrap i {
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    display: block;
    border-radius: 4px 4px 0 0;
}
.btgt .tgt-bar-wrap i.ok { background: linear-gradient(180deg, #43A047, #1B5E20); }
.btgt .tgt-bar-wrap i.no { background: linear-gradient(180deg, #EF9A9A, #C62828); }
.btgt .tgt-bar-wrap u {
    position: absolute;
    left: 0;
    width: 100%;
    height: 0;
    border-top: 2px dashed #33475B;
    opacity: 0.55;
}
.btgt .tgt-bar span {
    font-size: 9px;
    font-weight: 700;
    color: #7A8B7E;
}
.btgt .tgt-legend {
    display: flex;
    gap: 14px;
    margin-top: 10px;
    font-size: 11px;
    font-weight: 600;
    color: #5F6F63;
}
.btgt .tgt-legend span { display: flex; align-items: center; gap: 5px; }
.btgt .tgt-legend i.sw {
    width: 11px;
    height: 11px;
    border-radius: 3px;
    display: inline-block;
}
.btgt .tgt-legend i.sw.ok { background: #2E7D32; }
.btgt .tgt-legend i.sw.no { background: #C62828; }
.btgt .tgt-legend i.sw.line {
    height: 0;
    border-top: 2px dashed #33475B;
    border-radius: 0;
    width: 16px;
}
.btgt .tgt-tbl tr.tgt-hit  td { background: #F6FBF7; }
.btgt .tgt-tbl tr.tgt-miss td { background: #FFFAFA; }
/* --- Source Wise / CC Leads drawer tables --- */
.btgt .mx .tbl td.a,
.btgt .tbl td.a {
    color: #E65100;
}
/* Keep the wider GST tables readable inside the drawer */
.btgt .btgt .m-bd .tbl th,
.btgt .btgt .m-bd .tbl td {
    white-space: nowrap;
}

/* =========================================================
   PORTAL FULLSCREEN BACK BUTTON SPACE
========================================================= */

.btgt .btgt-head{
    padding-left:44px;
    min-height:40px;
}

javascript:
/* =========================================================================
   BRANCH TARGET & REALISATION — standalone page
   Extracted from branch-command-center (mTarget). Calls the same
   `branch_command_center` Server Script API and renders only the
   Target & Realisation view. Runs inside the Frappe desk context
   (frappe.call / frappe.datetime available).
   ========================================================================= */
(function(){
  "use strict";
  var root = document.querySelector(".btgt");
  if(!root) return;
  var $ = function(id){ return document.getElementById(id); };

  var curBranch = "";
  var D = null;               // holds the API message
  var ACTIVE_FROM = null, ACTIVE_TO = null;

  /* ---------- currency helpers (verbatim from command center) ---------- */
  var inr  = function(n){ return "\u20B9" + Math.round(n || 0).toLocaleString("en-IN"); };
  var inrS = function(n){
    n = n || 0;
    return n >= 1e7 ? "\u20B9"+(n/1e7).toFixed(2)+" Cr"
         : n >= 1e5 ? "\u20B9"+(n/1e5).toFixed(2)+" L"
         : inr(n);
  };
  var esc = function(s){ return (s==null?"":String(s)).replace(/[&<>"]/g,function(c){
    return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]; }); };

  function kpis(a){
    $("mKpis").innerHTML = a.map(function(k){
      return '<div class="m-kpi"><b class="num '+(k.c||"")+'">'+k.v+'</b><span>'+k.l+'</span></div>';
    }).join("");
  }
  function csec(t,c,b,open,red){
    open=open||false; red=red||false;
    return '<div class="csec '+(open?"open":"")+'"><button class="csec-h" data-acc="1">'+t+
      '<span class="cnt num '+(red?"r":"")+'">'+c+'</span><span class="car">\u25BC</span></button>'+
      '<div class="csec-b">'+b+'</div></div>';
  }

  /* ---------- Target & Realisation renderer (verbatim mTarget) ---------- */
  function mTarget(){
    var T = D.daily || null;

    if(!T || !T.days){
      kpis([{v:"\u2014",l:"Daily tracker unavailable"}]);
      $("mBody").innerHTML = '<div class="note">Update the branch_command_center '
        + 'Server Script to v16 to enable daily target tracking.</div>';
      return;
    }

    var onTrack = !!T.on_track;
    var closed = !!T.is_closed;
    var cycLbl = frappe.datetime.str_to_user(T.cycle_from)+" \u2192 "
               + frappe.datetime.str_to_user(T.cycle_to);

    kpis(closed
      ? [
          {v:T.pct+"%",        l:"Final Realisation", c:T.pct<70?"r":T.pct<85?"a":""},
          {v:inrS(T.achieved), l:"Achieved"},
          {v:inrS(T.target),   l:"Target"},
          {v:inrS(T.gap),      l:T.gap>0?"Shortfall":"Surplus", c:T.gap>0?"r":""},
          {v:T.hit_days,       l:"Days Hit"},
          {v:T.miss_days,      l:"Days Missed", c:"r"}
        ]
      : [
          {v:T.pct+"%",           l:"Cycle Realisation", c:T.pct<70?"r":T.pct<85?"a":""},
          {v:inrS(T.achieved),    l:"Achieved (net)"},
          {v:inrS(T.gross||0),    l:"Gross receipts"},
          {v:inrS(T.target),      l:"Monthly Target"},
          {v:inrS(T.gap),         l:"Gap to close",      c:"r"},
          {v:inrS(T.req_per_day), l:"NEEDED PER DAY",    c:"r"},
          {v:T.days_left,         l:"Days Left"}
        ]);

    var need = closed
      ? '<div class="tgt-need '+(T.pct>=100?"ok":"warn")+'">'
        + '<div class="tgt-need-l">Closed cycle \u00B7 '+cycLbl+'</div>'
        + '<div class="tgt-need-v">'+T.pct+'%<span> of target</span></div>'
        + '<div class="tgt-need-s">'+inrS(T.achieved)+' collected against '
          + inrS(T.target)+' \u2014 '
          + (T.gap>0 ? "short by "+inrS(T.gap) : "exceeded by "+inrS(T.achieved-T.target))
          + ' \u00B7 '+T.hit_days+' of '+T.total_days+' days hit</div>'
        + '</div>'
      : '<div class="tgt-need '+(onTrack?"ok":"warn")+'">'
        + '<div class="tgt-need-l">To hit '+inrS(T.target)+' by '
          + frappe.datetime.str_to_user(T.cycle_to)+'</div>'
        + '<div class="tgt-need-v">'+inr(T.req_per_day)+'<span> / day</span></div>'
        + '<div class="tgt-need-s">'+inrS(T.gap)+' still to collect across '
          + T.days_left+' remaining day'+(T.days_left===1?"":"s")+'</div>'
        + '</div>';

    var rr = closed
      ? '<div class="tgt-grid">'
        + '<div class="tgt-cell"><span>Average per day</span><b>'+inr(T.run_rate)+' / day</b></div>'
        + '<div class="tgt-cell"><span>Needed per day</span><b>'+inr(T.target/T.total_days)+' / day</b></div>'
        + '<div class="tgt-cell"><span>Result</span><b class="'+(T.pct>=100?"":"r")+'">'
          + (T.pct>=100 ? "TARGET MET" : "MISSED by "+inrS(T.gap))+'</b></div>'
        + '<div class="tgt-cell"><span>Cycle length</span><b>'+T.total_days+' days</b></div>'
        + '<div class="tgt-cell"><span>Days hit</span><b>'+T.hit_days+'</b></div>'
        + '<div class="tgt-cell"><span>Days missed</span><b class="r">'+T.miss_days+'</b></div>'
        + '</div>'
      : '<div class="tgt-grid">'
        + '<div class="tgt-cell"><span>Current run rate</span><b>'+inr(T.run_rate)+' / day</b></div>'
        + '<div class="tgt-cell"><span>Required run rate</span><b class="r">'+inr(T.req_per_day)+' / day</b></div>'
        + '<div class="tgt-cell"><span>Projected at this pace</span><b class="'+(onTrack?"":"r")+'">'
          + inrS(T.projected)+'</b></div>'
        + '<div class="tgt-cell"><span>Status</span><b class="'+(onTrack?"":"r")+'">'
          + (onTrack ? "ON TRACK" : "BEHIND by "+inrS(Math.max(T.target-T.projected,0)))+'</b></div>'
        + '<div class="tgt-cell"><span>Days hit</span><b>'+T.hit_days+'</b></div>'
        + '<div class="tgt-cell"><span>Days missed</span><b class="r">'+T.miss_days+'</b></div>'
        + '</div>';

    var elapsed = T.days.filter(function(d){ return !d.future; });
    var rows = elapsed.slice().reverse();

    var tbl = rows.length ? ('<div class="mx-wrap"><table class="tbl tgt-tbl"><thead><tr>'
      + '<th>Date</th><th class="num">Gross</th><th class="num">GST</th>'
      + '<th class="num">Loan cut</th><th class="num">Collected (net)</th>'
      + '<th class="num">Target that day</th><th class="num">+/-</th>'
      + '<th class="num">Cumulative</th><th>Result</th>'
      + '</tr></thead><tbody>'
      + rows.map(function(d){
          var ok = d.hit === 1;
          return '<tr class="'+(ok?"tgt-hit":"tgt-miss")+'">'
            + '<td><b>'+frappe.datetime.str_to_user(d.d)+'</b></td>'
            + '<td class="num" style="color:var(--mut)">'+inr(d.gross||0)+'</td>'
            + '<td class="num a">'+inr(d.gst||0)+'</td>'
            + '<td class="num" style="color:'+((d.cut||0)>0?"#C62828":"var(--mut)")+'">'
              + ((d.cut||0)>0 ? "-"+inr(d.cut) : "\u2014")+'</td>'
            + '<td class="num" style="font-weight:800">'+inr(d.got)+'</td>'
            + '<td class="num">'+inr(d.req)+'</td>'
            + '<td class="num" style="color:'+(ok?"#2E7D32":"#C62828")+'">'
              + (d.diff>=0?"+":"")+inr(d.diff)+'</td>'
            + '<td class="num" style="color:var(--mut)">'+inrS(d.cum)+'</td>'
            + '<td><span class="pill '+(ok?"p-g":"p-r")+'">'+(ok?"HIT":"MISS")+'</span></td>'
            + '</tr>';
        }).join('')
      + '<tr style="background:#F1F8E9;font-weight:800">'
        + '<td>TOTAL</td>'
        + '<td class="num">'+inr(T.gross||0)+'</td>'
        + '<td class="num">'+inr(T.gst||0)+'</td>'
        + '<td class="num">'+((T.cut||0)>0?"-"+inr(T.cut):"\u2014")+'</td>'
        + '<td class="num">'+inr(T.achieved)+'</td>'
        + '<td class="num"></td><td class="num"></td>'
        + '<td class="num">'+inrS(T.achieved)+'</td><td></td></tr>'
      + '</tbody></table></div>') : '<div class="note">No elapsed days in this cycle yet.</div>';

    var mx = Math.max.apply(null, elapsed.map(function(d){
      return Math.max(d.got, d.req); }).concat([1]));
    var strip = '<div class="tgt-strip">'
      + elapsed.map(function(d){
          var gh = Math.round((d.got/mx)*100);
          var rh = Math.round((d.req/mx)*100);
          return '<div class="tgt-bar" title="'+frappe.datetime.str_to_user(d.d)
            + ' \u2014 collected '+inr(d.got)+' of '+inr(d.req)+'">'
            + '<div class="tgt-bar-wrap">'
            +   '<i class="'+(d.hit?"ok":"no")+'" style="height:'+gh+'%"></i>'
            +   '<u style="bottom:'+rh+'%"></u>'
            + '</div>'
            + '<span>'+d.d.slice(8,10)+'</span></div>';
        }).join('')
      + '</div>'
      + '<div class="tgt-legend">'
      +   '<span><i class="sw ok"></i>Hit</span>'
      +   '<span><i class="sw no"></i>Miss</span>'
      +   '<span><i class="sw line"></i>Required that day</span>'
      + '</div>';

    $("mBody").innerHTML =
        need
      + csec("Pace check",6,rr,true)
      + csec("Daily collections vs required",elapsed.length,strip,true)
      + csec("Day by day \u2014 newest first",rows.length,tbl,true,true)
      + csec("How the daily target works",1,'<div class="formula">'
          + '<b>Basis \u2014 realisation is measured NET, not on gross receipts.</b><br>'
          + 'For every Payment Entry: <code>ex-GST = paid_amount \u00D7 100/105</code>, then '
          + 'loan modes lose a further <code>15% of ex-GST</code>. '
          + '<code>Collected (net) = ex-GST \u2212 loan cut</code>.<br>'
          + 'Loan modes: Bajaj, Sai Roshini, Fibe, Carepay, Savein, Loan Tap / Uno, '
          + 'ShopSE, Liqui Loans. Every other mode (Cash, Card, UPI, Bank, Razorpay) '
          + 'has GST removed but no cut.<br>'
          + 'This cycle: gross <b>'+inr(T.gross||0)+'</b> \u2212 GST <b>'+inr(T.gst||0)
          + '</b> \u2212 loan cut <b>'+inr(T.cut||0)+'</b> = <b>'+inr(T.achieved)+'</b>.<br><br>'
          + 'This uses the <b>deficit method</b>, not a flat daily split.<br><br>'
          + 'Each day: <code>target that day = (monthly target \u2212 collected so far) '
          + '\u00F7 days still remaining</code>.<br><br>'
          + 'So a miss automatically raises the bar for every day after it, and a big day '
          + 'lowers it. Cycle is <b>'+frappe.datetime.str_to_user(T.cycle_from)+' \u2192 '
          + frappe.datetime.str_to_user(T.cycle_to)+'</b> ('+T.total_days+' days, 6th\u21925th).<br><br>'
          + 'This tracker reports on whichever cycle the <b>range start</b> falls in, so the '
          + '<b>Last Cycle</b> preset shows that cycle\u2019s target and day-by-day result. '
          + 'The target is not pro-rated for a partial range \u2014 it is always the full '
          + 'cycle target of <b>'+inrS(T.target)+'</b>. '
          + 'Collections come from Payment Entry, <code>docstatus=1</code>, branch <b>'
          + esc(curBranch)+'</b>.</div>');
  }

  /* ---------- data load ---------- */
  function load(){
    $("mKpis").innerHTML = '<div class="m-kpi"><b>\u2026</b><span>Loading</span></div>';
    $("mBody").innerHTML = '<div class="note">Loading target data\u2026</div>';
    var args = { branch: curBranch };
    if(ACTIVE_FROM && ACTIVE_TO){ args.from_date = ACTIVE_FROM; args.to_date = ACTIVE_TO; }
    frappe.call({ method:"branch_command_center", args:args })
      .then(function(r){
        var m = r.message || {};
        D = { daily: m.daily || null };
        mTarget();
      })
      .catch(function(err){
        void 0;
        $("mBody").innerHTML = '<div class="note" style="color:#C62828">Error: '+esc(err.message||err)+'</div>';
      });
  }

  /* ---------- cycle presets (6th -> 5th) ---------- */
  function fmt(d){
    var y=d.getFullYear(), m=String(d.getMonth()+1).padStart(2,"0"), day=String(d.getDate()).padStart(2,"0");
    return y+"-"+m+"-"+day;
  }
  function setThisCycle(){
    var now=new Date(), yr=now.getFullYear(), mo=now.getMonth();
    if(now.getDate()<6) mo-=1;
    ACTIVE_FROM=fmt(new Date(yr,mo,6)); ACTIVE_TO=fmt(now);
    $("btgtFrom").value=ACTIVE_FROM; $("btgtTo").value=ACTIVE_TO;
  }
  function setLastCycle(){
    var now=new Date(), yr=now.getFullYear(), mo=now.getMonth();
    if(now.getDate()<6) mo-=1;
    ACTIVE_FROM=fmt(new Date(yr,mo-1,6)); ACTIVE_TO=fmt(new Date(yr,mo,5));
    $("btgtFrom").value=ACTIVE_FROM; $("btgtTo").value=ACTIVE_TO;
  }

  /* ---------- branch picker ---------- */
  function loadBranches(){
    return frappe.call({
      method:"frappe.client.get_list",
      args:{ doctype:"Branch", fields:["name"],
             filters:[["name","not in",["Head Office","Testing Branch"]]],
             order_by:"name asc", limit_page_length:1000 }
    }).then(function(r){
      var list=(r.message||[]).map(function(b){ return b.name; });
      var sel=$("btgtBranch");
      sel.innerHTML=list.map(function(b){ return '<option value="'+esc(b)+'">'+esc(b)+'</option>'; }).join("");
      if(list.length){ curBranch=list[0]; sel.value=curBranch; }
      return list;
    });
  }

  /* ---------- accordion (data-acc) ---------- */
  root.addEventListener("click", function(e){
    var acc=e.target.closest("[data-acc]");
    if(acc){ var sec=acc.closest(".csec"); if(sec) sec.classList.toggle("open"); }
  });

  /* ---------- events ---------- */
  function bind(){
    $("btgtBranch").addEventListener("change", function(){ curBranch=this.value; load(); });
    $("btgtApply").addEventListener("click", function(){
      ACTIVE_FROM=$("btgtFrom").value||null; ACTIVE_TO=$("btgtTo").value||null;
      root.querySelectorAll(".btgt-chip").forEach(function(c){ c.classList.remove("active"); });
      load();
    });
    root.querySelectorAll(".btgt-chip").forEach(function(chip){
      chip.addEventListener("click", function(){
        root.querySelectorAll(".btgt-chip").forEach(function(c){ c.classList.remove("active"); });
        chip.classList.add("active");
        if(chip.dataset.preset==="lastmonth") setLastCycle(); else setThisCycle();
        load();
      });
    });
  }

  /* ---------- init ---------- */
  function init(){
    if(typeof frappe==="undefined" || !frappe.call){
      $("mBody").innerHTML='<div class="note" style="color:#C62828">This page must run inside the Frappe desk (frappe.call unavailable).</div>';
      return;
    }
    bind();
    setThisCycle();
    root.querySelector('.btgt-chip[data-preset="thismonth"]').classList.add("active");
    loadBranches().then(function(){ load(); });
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
